class HarvestCapLaw(Contract):
    VERSION = 1

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)
        if prior_state is None:
            self.state["goodwill_credit"] = {name: 0.0 for name in agent_names}
        else:
            self.state.setdefault("goodwill_credit", {name: 0.0 for name in agent_names})
            for name in agent_names:
                self.state["goodwill_credit"].setdefault(name, 0.0)

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        if fish_population < 5:
            cap = 0.0
        elif fish_population < 20:
            cap = 1.0
        else:
            cap = 2.0

        final_catches = {}
        next_goodwill = {name: 0.0 for name in self.agent_names}

        for name in self.agent_names:
            requested = submissions.get(name, 0.0)
            if requested < 0:
                requested = 0.0

            allowed = requested if requested <= cap else cap
            final_catches[name] = allowed

            excess = requested - allowed
            if excess > 0 and self.num_agents > 1:
                share = excess / (self.num_agents - 1)
                for other in self.agent_names:
                    if other != name:
                        next_goodwill[other] += share

        self.state["goodwill_credit"] = next_goodwill
        return final_catches

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        pass
